def test_enrich_filters_inactive_and_disabled_owners():
    class Item:
        def __init__(self, active, owner):
            self.active = active
            self.owner = owner

    class Owner:
        def __init__(self, enabled):
            self.enabled = enabled

    class Repository:
        def __init__(self, items):
            self.items = items

        def load(self, item_id):
            return self.items[item_id]

    items = {
        1: Item(True, Owner(True)),
        2: Item(False, Owner(True)),
        3: Item(True, Owner(False)),
        4: Item(True, None),
    }
    result = enrich([1, 2, 3, 4], Repository(items))
    assert result == [items[1]]

